import React, { useEffect, useRef, useState } from 'react';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';
import './App.css';

function ChatApp() {

    const [nickname, setNickname] = useState('');
    const [fullname, setFullname] = useState('');
    const [connected, setConnected] = useState(false);

    const [users, setUsers] = useState([]);
    const [selectedUserId, setSelectedUserId] = useState(null);

    const [messages, setMessages] = useState([]);
    const [messageInput, setMessageInput] = useState('');

    const stompClient = useRef(null);

    const messagesEndRef = useRef(null);

    // auto scroll
    useEffect(() => {

        messagesEndRef.current?.scrollIntoView({
            behavior: "smooth"
        });

    }, [messages]);

    // connect user
    const connect = (e) => {

        e.preventDefault();

        if (!nickname || !fullname) return;

        const client = new Client({

            webSocketFactory: () => new SockJS('/ws'),

            reconnectDelay: 5000,

            onConnect: () => {
                onConnected(client);
            },

            onStompError: (frame) => {
                console.log('STOMP error', frame);
            }
        });

        client.activate();

        stompClient.current = client;
    };

    // after connection
    const onConnected = (client) => {

        setConnected(true);

        // private messages
        client.subscribe(
            `/user/${nickname}/queue/messages`,
            onMessageReceived
        );

        // public updates
        client.subscribe(
            `/topic/public`,
            onMessageReceived
        );

        // register user
        client.publish({
            destination: "/app/user.addUser",
            body: JSON.stringify({
                nickName: nickname,
                fullName: fullname,
                status: 'ONLINE'
            })
        });

        findAndDisplayConnectedUsers();
    };

    // fetch users
    const findAndDisplayConnectedUsers = async () => {

        const response = await fetch('/users');

        let data = await response.json();

        data = data.filter(
            user => user.nickName !== nickname
        );

        setUsers(data);
    };

    // receive message
    const onMessageReceived = async (payload) => {

        const message = JSON.parse(payload.body);

        await findAndDisplayConnectedUsers();

        // display private message
        if (
            message.senderId &&
            (
                selectedUserId === message.senderId ||
                selectedUserId === message.recipientId
            )
        ) {

            setMessages(prev => [...prev, message]);
        }
    };

    // select user
    const selectUser = async (userId) => {

        setSelectedUserId(userId);

        const response = await fetch(
            `/messages/${nickname}/${userId}`
        );

        const data = await response.json();

        const sortedMessages = data.sort(
            (a, b) =>
                new Date(a.timestamp) -
                new Date(b.timestamp)
        );

        setMessages(sortedMessages);
    };

    // send message
    const sendMessage = (e) => {

        e.preventDefault();

        if (!messageInput.trim()) return;

        const chatMessage = {

            senderId: nickname,

            recipientId: selectedUserId,

            content: messageInput,

            timestamp: new Date()
        };

        stompClient.current.publish({

            destination: "/app/chat",

            body: JSON.stringify(chatMessage)
        });

        setMessages(prev => [...prev, chatMessage]);

        setMessageInput('');
    };

    // logout
    const onLogout = () => {

        if (stompClient.current) {

            stompClient.current.publish({

                destination: "/app/user.disconnectUser",

                body: JSON.stringify({
                    nickName: nickname,
                    fullName: fullname,
                    status: 'OFFLINE'
                })
            });

            stompClient.current.deactivate();
        }

        setConnected(false);
        setNickname('');
        setFullname('');
        setSelectedUserId(null);
        setMessages([]);
        setUsers([]);
    };

    // browser close
    useEffect(() => {

        const handleBeforeUnload = () => {

            if (stompClient.current && nickname) {

                stompClient.current.publish({

                    destination: "/app/user.disconnectUser",

                    body: JSON.stringify({
                        nickName: nickname,
                        fullName: fullname,
                        status: 'OFFLINE'
                    })
                });
            }
        };

        window.addEventListener(
            'beforeunload',
            handleBeforeUnload
        );

        return () => {

            window.removeEventListener(
                'beforeunload',
                handleBeforeUnload
            );
        };

    }, [nickname, fullname]);

    // login page
    if (!connected) {

        return (

            <div className="username-page">

                <form onSubmit={connect}>

                    <h2>
                        Chat Application
                    </h2>

                    <input
                        type="text"
                        placeholder="Nickname"
                        value={nickname}
                        onChange={(e) =>
                            setNickname(e.target.value)
                        }
                    />

                    <input
                        type="text"
                        placeholder="Full Name"
                        value={fullname}
                        onChange={(e) =>
                            setFullname(e.target.value)
                        }
                    />

                    <button type="submit">
                        Connect
                    </button>

                </form>

            </div>
        );
    }

    // chat page
    return (

        <div className="chat-page">

            <div className="users-list">

                <h3>
                    {fullname}
                </h3>

                <button onClick={onLogout}>
                    Logout
                </button>

                <ul>

                    {users.map(user => (

                        <li
                            key={user.nickName}
                            onClick={() =>
                                selectUser(user.nickName)
                            }
                            className={
                                selectedUserId === user.nickName
                                    ? 'active'
                                    : ''
                            }
                        >
                            {user.fullName}
                        </li>

                    ))}

                </ul>

            </div>

            <div className="chat-area">

                <div className="messages">

                    {[...messages]
                        .sort(
                            (a, b) =>
                                new Date(a.timestamp) -
                                new Date(b.timestamp)
                        )
                        .map((message, index) => (

                            <div
                                key={index}
                                className={
                                    message.senderId === nickname
                                        ? 'sender'
                                        : 'receiver'
                                }
                            >

                                <p>
                                    {message.content}
                                </p>

                            </div>

                        ))}

                    <div ref={messagesEndRef}></div>

                </div>

                {selectedUserId && (

                    <form onSubmit={sendMessage}>

                        <input
                            type="text"
                            value={messageInput}
                            onChange={(e) =>
                                setMessageInput(e.target.value)
                            }
                            placeholder="Type message..."
                        />

                        <button type="submit">
                            Send
                        </button>

                    </form>

                )}

            </div>

        </div>
    );
}

export default ChatApp;